    "sh-ant": ["Deltoide anterior", "Press y elevaciones frontales."], "sh-lat": ["Deltoide lateral", "Da la anchura. Elevaciones laterales."], "sh-post": ["Deltoide posterior", "Pájaros, face pulls, contractora inversa."],
    "bi-long": ["Cabeza larga", "Parte externa: el «pico». Curls con el brazo por detrás del cuerpo."], "bi-short": ["Cabeza corta", "Parte interna. Curls con el codo por delante (predicador, concentrado)."], "bi-brach": ["Braquial", "Debajo del bíceps. Agarre neutro (martillo)."],
    "tr-long": ["Cabeza larga", "La más grande. Extensiones por encima de la cabeza y press francés."], "tr-lat": ["Cabeza lateral", "La «herradura» exterior. Extensiones en polea y fondos."], "tr-med": ["Cabeza medial", "Profunda; trabaja en todas las extensiones, sobre todo con agarre cerrado."],
